mapper.select:
SELECT 
FROM ydsz_flow_definition
WHERE flow_code = #{flowCode}
  AND version = #{version}
  AND tenant_id = #{tenantId}
  AND is_publish = 1
  AND status = 'ENABLED'
  AND deleted = 0
LIMIT 1

mapper.update:
UPDATE ydsz_flow_definition
SET is_publish = 9,
    updated_by = 0,
    updated_at = CURRENT_TIMESTAMP
WHERE flow_code = #{flowCode}
  AND tenant_id = #{tenantId}
  AND id != #{exceptId}
  AND is_publish = 1
  AND deleted = 0

mapper.select:
SELECT 
FROM ydsz_flow_definition
WHERE flow_code = #{flowCode}
  AND tenant_id = #{tenantId}
  AND deleted = 0
ORDER BY version DESC, created_at DESC

mapper.update:
UPDATE ydsz_flow_definition
SET locked_by = #{lockedBy},
    locked_at = #{lockedAt},
    version = version + 1,
    updated_at = CURRENT_TIMESTAMP
WHERE id = #{id}
  AND version = #{version}
  AND deleted = 0
  AND (
        locked_by IS NULL
     OR locked_by = #{expectedOldBy}
     OR locked_at < #{timeoutExpired}
  )

UPDATE ydsz_flow_definition
SET locked_by = NULL,
    locked_at = NULL,
    version = version + 1,
    updated_at = CURRENT_TIMESTAMP
WHERE id = #{id}
  AND locked_by = #{expectedBy}
  AND version = #{version}
  AND deleted = 0
